import{_ as a,o as t,c as i,ag as n}from"./chunks/framework.HcBc_Mb9.js";const r="/anthropic-notes/assets/4D.E0peSGF4.png",m=JSON.parse('{"title":"AI Fluency Framework","description":"","frontmatter":{},"headers":[],"relativePath":"ai-fluency/01-ai-fluency-framework.md","filePath":"ai-fluency/01-ai-fluency-framework.md"}'),o={name:"ai-fluency/01-ai-fluency-framework.md"};function s(l,e,c,h,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-fluency-framework" tabindex="-1">AI Fluency Framework <a class="header-anchor" href="#ai-fluency-framework" aria-label="Permalink to &quot;AI Fluency Framework&quot;">​</a></h1><h2 id="why-do-we-need-ai-fluency" tabindex="-1">Why do we need AI Fluency? <a class="header-anchor" href="#why-do-we-need-ai-fluency" aria-label="Permalink to &quot;Why do we need AI Fluency?&quot;">​</a></h2><p>AI influency isn&#39;t just about being a technical expert or memorizing the 10 best prompts whatever trending task is popular this month. It&#39;s about developing a collection of practical skills, knowledge, insights, and values that reinforce each other.</p><p>This chapter explores what it really means to be &quot;fluent&quot; with AI and why this matters. We discuss how AI Fluency involves developing practical skills, knowledge, insights, and values that help you interact with AI systems in ways that are effective, efficient, ethical, and safe. We also introduce three ways people engage with AI:</p><ul><li>Automation: The AI completes specific tasks based on your instructions.</li><li>Augmentation: You and AI collaborate as creative thinking and task execution partners.</li><li>Agency: You configure AI to work independently on your behalf, establishing its knowledge and behavior patterns rather than just giving it specific tasks.</li></ul><h2 id="the-4d-framework" tabindex="-1">The 4D Framework <a class="header-anchor" href="#the-4d-framework" aria-label="Permalink to &quot;The 4D Framework&quot;">​</a></h2><p>The AI Fluency Framework consists of four core competencies (the 4Ds):<br> Delegation: Deciding what work to do with AI vs. yourself<br> Description: Communicating effectively with AI systems<br> Discernment: Evaluating AI outputs critically<br> Diligence: Ensuring responsible AI collaboration<br></p><div style="text-align:center;margin:20px 0;"><img src="'+r+'" alt="4D framework showing Delegation, Description, Discernment, Diligence" style="max-width:720px;width:60%;height:auto;border-radius:12px;"></div><h3 id="_1-delegation" tabindex="-1">1) Delegation <a class="header-anchor" href="#_1-delegation" aria-label="Permalink to &quot;1) Delegation&quot;">​</a></h3><p>Understand your goal and the problem that you are trying to solve<br> Know what AI systems can and can&#39;t do<br> Decide how to divide the work between you and the AI</p><h3 id="_2-description" tabindex="-1">2) Description <a class="header-anchor" href="#_2-description" aria-label="Permalink to &quot;2) Description&quot;">​</a></h3><p>What you want the final output to be<br> How you want the AI to approach the task<br> How you want the AI to behave</p><h3 id="_3-discernment" tabindex="-1">3) Discernment <a class="header-anchor" href="#_3-discernment" aria-label="Permalink to &quot;3) Discernment&quot;">​</a></h3><p>Is the output useful and correct?<br> Is the AI taking the right approach?<br> Is the AI behaving as desired?</p><h3 id="_4-diligence" tabindex="-1">4) Diligence <a class="header-anchor" href="#_4-diligence" aria-label="Permalink to &quot;4) Diligence&quot;">​</a></h3><p>Ensuring accuracy and taking responsibility<br> Honesty and transparency<br> Ethical use and critical awareness</p>',16)])])}const f=a(o,[["render",s]]);export{m as __pageData,f as default};
